-- k175: çiçek takvimi talep akışı. Talep tek kayıt (il başına), arka plan işi yalnız kaynak havuzundan (TAGEM AAEM/51) yayınlar; kaynak yoksa «kaynak bekleniyor», uygulamada «Veri yok».
create table if not exists public.cicek_kaynak_havuz (
  id bigserial primary key, il text not null, ilce text not null, ay1 smallint, ay2 smallint, donem text, nektar text, polen text,
  baskin_flora text, resmi_ay_araligi text, dogrulandi boolean not null default true, kaynak text not null, created_at timestamptz not null default now(),
  unique (il, ilce, donem)
);
alter table public.cicek_kaynak_havuz enable row level security;
drop policy if exists cicek_kaynak_havuz_admin on public.cicek_kaynak_havuz;
create policy cicek_kaynak_havuz_admin on public.cicek_kaynak_havuz for all using (public.sa_is_admin()) with check (public.sa_is_admin());

alter table public.takvim_eksik add column if not exists durum text not null default 'bekliyor';
alter table public.takvim_eksik add column if not exists istek_sayisi integer not null default 1;
alter table public.takvim_eksik add column if not exists son_istek timestamptz not null default now();
alter table public.takvim_eksik add column if not exists islendi_at timestamptz;
alter table public.takvim_eksik add column if not exists kaynak_not text;
alter table public.takvim_eksik drop constraint if exists takvim_eksik_durum_chk;
alter table public.takvim_eksik add constraint takvim_eksik_durum_chk check (durum in ('bekliyor','hazirlandi','kaynak_yok'));
delete from public.takvim_eksik a using public.takvim_eksik b where lower(a.il) = lower(b.il) and a.id > b.id;
create unique index if not exists takvim_eksik_il_tek on public.takvim_eksik (lower(il));

create or replace function public.sa_takvim_il_norm(p text) returns text language sql immutable as $$
  select x from unnest(array['Adana','Adıyaman','Afyonkarahisar','Ağrı','Amasya','Ankara','Antalya','Artvin','Aydın','Balıkesir','Bilecik','Bingöl','Bitlis','Bolu','Burdur','Bursa','Çanakkale','Çankırı','Çorum','Denizli','Diyarbakır','Edirne','Elazığ','Erzincan','Erzurum','Eskişehir','Gaziantep','Giresun','Gümüşhane','Hakkari','Hatay','Isparta','Mersin','İstanbul','İzmir','Kars','Kastamonu','Kayseri','Kırklareli','Kırşehir','Kocaeli','Konya','Kütahya','Malatya','Manisa','Kahramanmaraş','Mardin','Muğla','Muş','Nevşehir','Niğde','Ordu','Rize','Sakarya','Samsun','Siirt','Sinop','Sivas','Tekirdağ','Tokat','Trabzon','Tunceli','Şanlıurfa','Uşak','Van','Yozgat','Zonguldak','Aksaray','Bayburt','Karaman','Kırıkkale','Batman','Şırnak','Bartın','Ardahan','Iğdır','Yalova','Karabük','Kilis','Osmaniye','Düzce']::text[]) x
  where replace(replace(lower(replace(replace(x,'İ','i'),'I','ı')),' ',''),'.','') = replace(replace(lower(replace(replace(trim(coalesce(p,'')),'İ','i'),'I','ı')),' ',''),'.','') limit 1
$$;

-- Talep: il başına tek kayıt (tekrar → sayaç). Takvimi zaten olan il için kayıt yok.
create or replace function public.sa_takvim_iste(p_il text) returns text language plpgsql security definer set search_path = public as $$
declare v text := public.sa_takvim_il_norm(p_il); d text;
begin
  if v is null then return 'gecersiz'; end if;
  if exists (select 1 from public.cicek_takvimi where il = v) then return 'var'; end if;
  on conflict ((lower(il))) do update set istek_sayisi = public.takvim_eksik.istek_sayisi + 1, son_istek = now()
  returning durum into d;
  return d;
end $$;
revoke all on function public.sa_takvim_iste(text) from public;
grant execute on function public.sa_takvim_iste(text) to anon, authenticated;

-- Arılık açılınca / il değişince: takvimi olmayan il için talep.
create or replace function public.sa_arilik_takvim_talep() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(new.deleted,false) = false and new.data ? 'il' and (tg_op = 'INSERT' or (old.data->>'il') is distinct from (new.data->>'il')) then
    perform public.sa_takvim_iste(new.data->>'il');
  end if;
  return new;
end $$;
drop trigger if exists arilik_takvim_talep on public.apiaries;
create trigger arilik_takvim_talep after insert or update of data on public.apiaries for each row execute function public.sa_arilik_takvim_talep();

-- Arka plan işi: yalnız kaynak havuzundaki doğrulanmış satırları yayınlar; uydurma yok.
create or replace function public.sa_takvim_isle() returns integer language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0; k integer;
begin
  for r in select * from public.takvim_eksik where durum in ('bekliyor','kaynak_yok') order by son_istek loop
    if exists (select 1 from public.cicek_takvimi where il = r.il) then
      update public.takvim_eksik set durum = 'hazirlandi', islendi_at = now(), kaynak_not = coalesce(kaynak_not, 'takvim zaten var') where id = r.id; n := n + 1;
    elsif exists (select 1 from public.cicek_kaynak_havuz where il = r.il and dogrulandi) then
        select il, ilce, ay1, ay2, donem, nektar, polen, baskin_flora, resmi_ay_araligi, dogrulandi, kaynak from public.cicek_kaynak_havuz where il = r.il and dogrulandi;
      get diagnostics k = row_count;
      update public.takvim_eksik set durum = 'hazirlandi', islendi_at = now(), kaynak_not = k || ' ilçe satırı · TAGEM AAEM/51 (2022)' where id = r.id; n := n + 1;
    else
      update public.takvim_eksik set durum = 'kaynak_yok', islendi_at = now(), kaynak_not = 'Kaynak bekleniyor: TAGEM AAEM/51 Tablo 1''de bu il ayrıştırılamadı; il tarım müdürlüğü / Arıcılık Araştırma Enstitüsü / akademik flora çalışması aranıyor' where id = r.id;
    end if;
  end loop;
  return n;
end $$;
revoke all on function public.sa_takvim_isle() from public, anon, authenticated;

-- Yönetici listesi
create or replace function public.sa_takvim_talepleri() returns table (il text, durum text, istek_sayisi integer, created_at timestamptz, son_istek timestamptz, islendi_at timestamptz, kaynak_not text, kaynak text)
language plpgsql security definer set search_path = public as $$
begin
  if not public.sa_is_admin() then raise exception 'Yalnız yönetici' using errcode = '42501'; end if;
  return query select t.il, t.durum, t.istek_sayisi, t.created_at, t.son_istek, t.islendi_at, t.kaynak_not,
    (select string_agg(distinct split_part(c.kaynak, ' — ', 1), ' · ') from public.cicek_takvimi c where c.il = t.il)
  from public.takvim_eksik t order by t.son_istek desc;
end $$;
grant execute on function public.sa_takvim_talepleri() to authenticated;

do $c$ begin
  perform cron.unschedule('cicek-takvim-isle') where exists (select 1 from cron.job where jobname = 'cicek-takvim-isle');
  perform cron.schedule('cicek-takvim-isle', '*/10 * * * *', 'select public.sa_takvim_isle()');
end $c$;
on conflict do nothing;
update public.yapilacaklar set baslik = 'Çiçek takvimi: talep gelince il ekleme',
  aciklama = 'Yüklü: Rize, Erzurum, Ordu, Artvin, Muğla, Antalya. Akış: arılık açılınca / il seçilince takvimi olmayan il → takvim_eksik''e il başına tek kayıt (sa_takvim_iste, tekrar → sayaç). Arka plan işi cicek-takvim-isle (pg_cron 10 dk, sa_takvim_isle) yalnız kaynak havuzundan (cicek_kaynak_havuz: TAGEM AAEM/51 2022 Tablo 1, 56 il, resmî ilçe listesiyle eşleşen satırlar) yayınlar → «hazırlandı», uygulama önbelleğe alıp kendiliğinden gösterir. Kaynak yoksa «kaynak bekleniyor» (uygulamada «Veri yok»); havuzda olmayan 19 il: Bingöl, Çanakkale, Erzincan, Giresun, Mersin, Kahramanmaraş, Muş, Nevşehir, Niğde, Uşak, Zonguldak, Bayburt, Kırıkkale, Bartın, Ardahan, Iğdır, Yalova, Karabük, Kilis — il tarım müdürlüğü / AAE / akademik flora kaynağı eklenince havuza girer.'
where id = 3;
